def transform(g):
    from collections import Counter
    c=Counter(x for row in g for x in row)
    colors=sorted(c,key=lambda k:-c[k])
    bg,sparse=colors[0],colors[1]
    out=[row[:] for row in g]
    for r in range(len(g)):
        for j in range(1,len(g[r])-1):
            if g[r][j]==bg and g[r][j-1]==sparse and g[r][j+1]==sparse:
                out[r][j]=2
    return out
